create table public.chat_timeline_consents(conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,enabled boolean not null default false,primary key(conversation_id,user_id));
alter table public.chat_timeline_consents enable row level security;revoke all on public.chat_timeline_consents from anon,authenticated;grant select on public.chat_timeline_consents to authenticated;
create policy timeline_consent_member_read on public.chat_timeline_consents for select to authenticated using(public.is_conversation_member(conversation_id));
create or replace function public.chat_timeline_allowed(target_conversation_id uuid) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and public.is_conversation_member(target_conversation_id) and exists(select 1 from public.conversations where id=target_conversation_id and kind='direct') and(select count(*) from public.conversation_members where conversation_id=target_conversation_id)=2 and(select count(*) from public.chat_timeline_consents t join public.conversation_members cm on cm.conversation_id=t.conversation_id and cm.user_id=t.user_id where t.conversation_id=target_conversation_id and t.enabled)=2;$$;
create or replace function public.set_chat_timeline_consent(target_conversation_id uuid,allow_timeline boolean) returns void language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null or allow_timeline is null or not public.is_conversation_member(target_conversation_id) or not exists(select 1 from public.conversations where id=target_conversation_id and kind='direct') then raise exception 'Choose a direct conversation';end if;
 insert into public.chat_timeline_consents values(target_conversation_id,auth.uid(),allow_timeline) on conflict(conversation_id,user_id) do update set enabled=excluded.enabled;
end;$$;
create table public.chat_friendship_milestones(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,created_by uuid not null references auth.users(id) on delete cascade,title text not null check(length(title) between 1 and 300),happened_at timestamptz not null,created_at timestamptz not null default now());
alter table public.chat_friendship_milestones enable row level security;revoke all on public.chat_friendship_milestones from anon,authenticated;grant select,insert,delete on public.chat_friendship_milestones to authenticated;
create policy milestones_consensual_read on public.chat_friendship_milestones for select to authenticated using(created_by=(select auth.uid()) or public.chat_timeline_allowed(conversation_id));
create policy milestones_consensual_insert on public.chat_friendship_milestones for insert to authenticated with check(created_by=(select auth.uid()) and public.chat_timeline_allowed(conversation_id));
create policy milestones_own_delete on public.chat_friendship_milestones for delete to authenticated using(created_by=(select auth.uid()));
create or replace function public.get_chat_friendship_timeline(target_conversation_id uuid) returns table(id uuid,conversation_id uuid,sender_id uuid,body text,created_at timestamptz,message_type text,expires_at timestamptz) language plpgsql stable security invoker set search_path='' as $$begin
 if not public.chat_timeline_allowed(target_conversation_id) then raise exception 'Both people must enable this timeline';end if;
 return query select m.id,m.conversation_id,m.sender_id,m.body,m.created_at,m.message_type,m.expires_at from public.chat_messages m where m.conversation_id=target_conversation_id order by m.created_at,m.id limit 100;
end;$$;
revoke all on function public.chat_timeline_allowed(uuid),public.set_chat_timeline_consent(uuid,boolean),public.get_chat_friendship_timeline(uuid) from public,anon;
grant execute on function public.chat_timeline_allowed(uuid),public.set_chat_timeline_consent(uuid,boolean),public.get_chat_friendship_timeline(uuid) to authenticated;
